#!/usr/bin/env bash
# Runs the Julia model with the given config (default: out/default.yaml, as
# generated by scripts/params_to_config.py). Output goes to the given
# directory (default: out/julia/).
set -euo pipefail
cd "$(dirname "$0")/.."
config="${1:-out/default.yaml}"
out_dir="${2:-out/julia}"
julia --project=../PWNModel.jl -e 'using PWNModel; run_model(ARGS[1]; out_dir=ARGS[2])' "$config" "$out_dir"
